{
  "findings": [
    {
      "check_id": "CKV_AZURE_26",
      "title": "MSSQL security alerts have no notification recipients",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The alert policy is enabled but does not configure email_addresses, so designated security responders will not receive threat-detection alerts."
    },
    {
      "check_id": "CKV_AZURE_27",
      "title": "MSSQL security alerts are not sent to account administrators",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The policy does not enable email_account_admins, preventing service and account administrators from automatically receiving security alerts."
    },
    {
      "check_id": "CKV_AZURE_25",
      "title": "MSSQL threat detection does not cover all alert types",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The policy explicitly disables SQL injection and data exfiltration alerts, leaving significant database attack and data-loss activity undetected."
    }
  ],
  "patched_code": "variable \"security_alert_email_addresses\" {\n  description = \"Email addresses that receive MSSQL security alerts.\"\n  type        = list(string)\n  sensitive   = true\n\n  validation {\n    condition = length(var.security_alert_email_addresses) > 0 && alltrue([\n      for address in var.security_alert_email_addresses : trimspace(address) != \"\"\n    ])\n    error_message = \"At least one non-empty MSSQL security alert email address must be provided.\"\n  }\n}\n\nresource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n  email_addresses            = var.security_alert_email_addresses\n  email_account_admins       = true\n  disabled_alerts            = []\n  retention_days             = 20\n}\n",
  "fix_summary": "Enabled notifications to configured security recipients and account administrators. Removed the disabled threat categories so all supported MSSQL threat-detection alerts remain active."
}
